PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/rev/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?series WHERE {
  ?zone brick:hasSubclass* ?r ;
        rdfs:label "DataCenter_basement_ZN_6" .
  ?point brick:isPointOf ?zone ;
         brick:hasType brick:Air_Temperature .
  ?point ref:hasTimeseriesId ?series .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z WHERE {
  ?z rdfs:label "DataCenter_basement_ZN_6" .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?z WHERE {
  ?z brick:hasSubclass* brick:Zone .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/rev/>
SELECT ?point ?series ?type WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z06> .
  OPTIONAL { ?point ref:hasTimeseriesId ?series . }
  OPTIONAL { ?point brick:hasType ?type . }
}

SELECT ?point ?type ?series WHERE {
  ?point ?type brick:Air_Temperature .
  OPTIONAL { ?point ?p ?o . }
  OPTIONAL { ?point ref:hasTimeseriesId ?series . }
} LIMIT 50

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?point ?series WHERE {
  ?point brick:isPointOf ?zone .
  ?point brick:hasType brick:Air_Temperature .
  OPTIONAL { ?point ref:hasTimeseriesId ?series . }
  FILTER(STR(?zone) LIKE "%Zone_F2_Z06%")
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?point ?zone ?series WHERE {
